1	#![allow(dead_code)]
2	use crate::belnap::*;
3	use crate::tokens::*;
4	use crate::frob_verify::FrobeniusHarness;
5	
6	/// Maximum simultaneous FSPLIT fork depth. Real programs never nest this deep;
7	/// the cap is a safety bound, and exceeding it is now counted (`fork_overflow`)
8	/// rather than dropped silently.
9	const FORK_STACK_CAP: usize = 64;
10	
11	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
12	pub enum Phase { Boot, Think, Act, Observe, Update, Halt }
13	
14	/// A fork frame pushed when FSPLIT bifurcates execution.
15	/// Tracks the two parallel branches until FFUSE joins them.
16	#[derive(Copy, Clone)]
17	struct ForkFrame {
18	    /// Position just after the matching FFUSE (where to resume after join).
19	    resume_ip: usize,
20	    /// The value carried on the right branch (gated by EVALT/EVALF).
21	    right_val: B4,
22	    /// Whether the right branch has been populated.
23	    right_set: bool,
24	}
25	
26	/// Structural snapshot computed by IMSCRIB.
27	/// Dynamic fields (b_live_ticks, gate_discriminations, value_period) are
28	/// overlaid from runtime accumulators after the static classification.
29	#[derive(Copy, Clone, PartialEq)]
30	pub struct Snapshot {
31	    pub frobenius_order: u8,
32	    pub period: usize,
33	    pub sig: (usize, usize, usize, usize), // (L, F, D, X)
34	    pub token_diversity: usize,
35	    pub self_ref: bool,
36	    pub dialetheia_complete: bool,
37	    pub tier: u8,
38	    // ── Dynamic (runtime) fields ──
39	    pub b_live_ticks: u64,           // ticks where B was on stack when EVALT or EVALF fired
40	    pub gate_discriminations: u64,   // ticks where EVALT actually passed T, or EVALF passed F
41	    pub value_period: usize,         // measured period of stack-top value trace (0 = not yet known)
42	    // ── SIXTEEN_3 / R2 fields (O_inf_dag, lateral replicative opening) ──
43	    // Mirror the Lean kernel's R2 triple (dim=dead, top=mime, prot=ah) as three
44	    // independent structural/runtime conditions rather than one boolean, per the
45	    // discerning ob3ect run (2026-07-15): atomicity, bifurcation, winding.
46	    pub atomic_reentry: bool,        // "dim=dead": exactly one FSPLIT/FFUSE pair — a
47	                                      // point-like fork, not an elaborate nested structure
48	    pub bifurcation_revisited: bool, // "top=mime": that single fork point recurs every wrap
49	                                      // (bowtie/figure-8), distinct from mere periodicity
50	    pub winding_count: u32,          // "prot=ah": protected integer winding — a monotonic
51	                                      // full-program-pass counter that never resets
52	}
53	
54	impl Snapshot {
55	    pub fn tier_name(self) -> &'static str {
56	        match self.tier {
57	            1 => "O_1", 2 => "O_2", 3 => "O_inf",
58	            4 => "O_inf_dag", // LATERAL to O_inf, not above it — see compute_tier
59	            _ => "O_0",
60	        }
61	    }
62	
63	    /// The ⊥ mirror: exchange the R1 (O_∞) and R2 (O_inf_dag) evidence triples,
64	    /// role for role, leaving the shared substrate (self_ref, frobenius_order,
65	    /// period, value_period, sig, diversity) untouched — the two dialects sit on
66	    /// one temporal substrate; only the evidence changes hands:
67	    ///   static mark:   dialetheia_complete      ↔ atomic_reentry
68	    ///   counted act:   b_live_ticks             ↔ winding_count
69	    ///   recurrence:    gate_discriminations > 0 ↔ bifurcation_revisited
70	    /// The count↔bool leg passes through the canonical section (true ↦ 1),
71	    /// so mirrored() alone is involutive on the witness plane, not on raw
72	    /// counts. The exact involution is Kernel::arev_hop, which is parity over
73	    /// unchanged accumulators — the door, not the mirror.
74	    pub fn mirrored(self) -> Snapshot {
75	        let mut m = self;
76	        m.dialetheia_complete = self.atomic_reentry;
77	        m.atomic_reentry      = self.dialetheia_complete;
78	        m.b_live_ticks        = self.winding_count as u64;
79	        m.winding_count       = self.b_live_ticks.min(u32::MAX as u64) as u32;
80	        m.gate_discriminations   = if self.bifurcation_revisited { 1 } else { 0 };
81	        m.bifurcation_revisited  = self.gate_discriminations > 0;
82	        m.tier = compute_tier(&m);
83	        m
84	    }
85	}
86	
87	/// Graph-execution kernel.
88	/// FSPLIT creates fork frames. FFUSE joins them.
89	/// Program is inherently cyclic: end wraps to start.
90	/// TANCH at root depth sinks the wire -> halt.
91	pub struct Kernel {
92	    pub program:     Program,
93	    pub ip:          usize,
94	    pub phase:       Phase,
95	    pub tick_count:  u64,
96	    pub memory:      B4Memory,
97	    pub stack:       B4Stack,
98	    pub registers:   B4Registers,
99	    pub snapshot:    Option<Snapshot>,
100	    pub frob_checks: u64,
101	    pub frob_open:   u64,
102	    pub harness:     FrobeniusHarness,
103	    fork_stack:      [ForkFrame; FORK_STACK_CAP],
104	    fork_depth:      usize,
105	    pub fork_overflow: u64,   // FSPLITs that exceeded FORK_STACK_CAP (0 in practice)
106	    pub halted:      bool,
107	    pub dynamic_mode: bool,  // true → rebuild program from IgTuple each wrap
108	    // ── Cross-dialect ruleset state ──
109	    pub active_dialect: u8,        // 0-87, current active ruleset (default 0 = canonical)
110	    /// ⊥ (chirality): false = or' reading (R1-dominant, the canonical hand),
111	    /// true = flipped — the kernel reads its own snapshot through the mirror
112	    /// (O_∞ ↔ O_inf_dag lateral hop, the ob3ect's AREV step 15). Toggled by
113	    /// arev_hop(); parity over unchanged accumulators, so hop∘hop = id exactly.
114	    pub chirality: bool,
115	    pub liminal_target: Option<u8>, // dialect jumped to, pending IFIX seal
116	    pub liminal_compound: Option<u8>,   // compound index (0-10) used for liminal jump
117	    // ── Runtime accumulators for dynamic snapshot fields ──
118	    b_live_count:             u64,
119	    gate_discrimination_count: u64,
120	    value_trace:              [B4; 16],   // ring buffer of stack-top values after each tick
121	    value_trace_head:         usize,
122	    winding_count:            u32,   // protected: incremented on every natural end-of-program
123	                                      // wrap, never reset (not even by disable_dynamic)
124	}
125	
126	impl Kernel {
127	    pub fn new() -> Self {
128	        Self {
129	            program:     bootstrap_loop(),
130	            ip:          0,
131	            phase:       Phase::Boot,
132	            tick_count:  0,
133	            memory:      B4Memory::new(),
134	            stack:       B4Stack::new(),
135	            registers:   B4Registers::new(),
136	            snapshot:    None,
137	            frob_checks: 0,
138	            frob_open:   0,
139	            harness:     FrobeniusHarness::new("mOMonadOS"),
140	            fork_stack:  [ForkFrame { resume_ip: 0, right_val: B4::N, right_set: false }; FORK_STACK_CAP],
141	            fork_depth:  0,
142	            fork_overflow: 0,
143	            halted:      false,
144	            dynamic_mode: false,
145	            active_dialect:      0,
146	            chirality:           false,
147	            liminal_target:       None,
148	            liminal_compound:     None,
149	            b_live_count:             0,
150	            gate_discrimination_count: 0,
151	            value_trace:              [B4::N; 16],
152	            value_trace_head:         0,
153	            winding_count:            0,
154	        }
155	    }
156	
157	    pub fn boot(&mut self) {
158	        self.snapshot = Some(self_imscribe(&self.program));
159	        self.phase = Phase::Think;
160	    }
161	
162	    fn in_fork(&self) -> bool { self.fork_depth > 0 }
163	    pub fn fork_depth(&self) -> usize { self.fork_depth }
164	
165	    fn push_fork(&mut self, resume_ip: usize) {
166	        if self.fork_depth < FORK_STACK_CAP {
167	            self.fork_stack[self.fork_depth] = ForkFrame {
168	                resume_ip,
169	                right_val: B4::N,
170	                right_set: false,
171	            };
172	            self.fork_depth += 1;
173	        } else {
174	            // Fork stack full: record the overflow rather than dropping the fork
175	            // silently (a silent drop would desync the matching FFUSE). This path
176	            // is unreachable for real programs; it makes a pathological nest
177	            // observable instead of invisible.
178	            self.fork_overflow += 1;
179	        }
180	    }
181	
182	    fn pop_fork(&mut self) -> Option<ForkFrame> {
183	        if self.fork_depth > 0 {
184	            self.fork_depth -= 1;
185	            Some(self.fork_stack[self.fork_depth])
186	        } else {
187	            None
188	        }
189	    }
190	
191	    fn fork_top_mut(&mut self) -> Option<&mut ForkFrame> {
192	        if self.fork_depth > 0 {
193	            Some(&mut self.fork_stack[self.fork_depth - 1])
194	        } else {
195	            None
196	        }
197	    }
198	
199	    /// Find matching FFUSE for FSPLIT at split_ip via balanced parenthesis scan.
200	    pub fn find_matching_ffuse(&self, split_ip: usize) -> usize {
201	        let mut depth = 1u32;
202	        let n = self.program.len();
203	        if n == 0 { return 0; }
204	        let mut i = (split_ip + 1) % n;
205	        let start = i;
206	        loop {
207	            match self.program.get(i) {
208	                Some(Token::Fsplit) => depth += 1,
209	                Some(Token::Ffuse)  => {
210	                    depth -= 1;
211	                    if depth == 0 { return i; }
212	                }
213	                _ => {}
214	            }
215	            i = (i + 1) % n;
216	            if i == start { break; }
217	        }
218	        n // unmatched
219	    }
220	
221	    /// Find matching FFUSE3 for FSPLIT3 at split_ip via balanced parenthesis scan.
222	    pub fn find_matching_ffuse3(&self, split_ip: usize) -> usize {
223	        let mut depth = 1u32;
224	        let n = self.program.len();
225	        if n == 0 { return 0; }
226	        let mut i = (split_ip + 1) % n;
227	        let start = i;
228	        loop {
229	            match self.program.get(i) {
230	                Some(Token::Fsplit3) => depth += 1,
231	                Some(Token::Ffuse3)  => {
232	                    depth -= 1;
233	                    if depth == 0 { return i; }
234	                }
235	                _ => {}
236	            }
237	            i = (i + 1) % n;
238	            if i == start { break; }
239	        }
240	        n // unmatched
241	    }
242	
243	    /// One Frobenius tick. Returns false if halted.
244	    pub fn tick(&mut self) -> bool {
245	        if self.phase == Phase::Halt || self.halted { return false; }
246	        self.tick_count += 1;
247	
248	        // THINK
249	        self.phase = Phase::Think;
250	        // ── Use dynamic_imscribe so tier reflects runtime behavior ──
251	        self.snapshot = Some(self.dynamic_imscribe());
252	        self.maybe_promote();
253	
254	        // ACT
255	        self.phase = Phase::Act;
256	        if self.ip >= self.program.len() {
257	            self.ip = 0;
258	            self.try_self_modify();
259	        }
260	        let tok = self.program.get(self.ip).unwrap();
261	
262	        let mut next_ip = self.ip + 1;
263	        if next_ip >= self.program.len() {
264	            next_ip = 0;
265	            // Natural full-program wrap — protected winding, never reset. FFUSE's
266	            // jump-to-resume below can also land next_ip at 0, but that's a fork
267	            // resume, not a completed pass, so it does not increment this.
268	            self.winding_count = self.winding_count.saturating_add(1);
269	        }
270	
271	        match tok {
272	            Token::Vinit => {
273	                self.stack.push(B4::N);
274	            }
275	            Token::Tanch => {
276	                let val = self.stack.pop();
277	                let addr = self.registers.read(0) as usize;
278	                self.memory.write(addr, val);
279	                if !self.in_fork() {
280	                    self.phase = Phase::Halt;
281	                    self.halted = true;
282	                    return false;
283	                }
284	            }
285	            Token::Afwd => {
286	                let r0 = self.registers.read(0) as u8;
287	                self.registers.write(0, B4::from_u8(r0.wrapping_add(1)));
288	            }
289	            Token::Arev => {
290	                let r0 = self.registers.read(0) as u8;
291	                self.registers.write(0, B4::from_u8(r0.wrapping_sub(1)));
292	            }
293	            Token::Clink => {
294	                let a = self.registers.read(1);
295	                let b = self.registers.read(2);
296	                self.registers.write(3, b4_meet(a, b));
297	            }
298	            Token::Imscrib => {
299	                if let Some(snap) = self.snapshot {
300	                    self.registers.write(4, B4::from_u8(snap.token_diversity as u8 & 3));
301	                    self.registers.write(5, if snap.self_ref           { B4::T } else { B4::F });
302	                    self.registers.write(6, if snap.frobenius_order > 0 { B4::T } else { B4::F });
303	                    self.registers.write(7, if snap.dialetheia_complete { B4::T } else { B4::F });
304	                }
305	            }
306	            Token::Fsplit => {
307	                let v = self.stack.peek();
308	                let ffuse_ip = self.find_matching_ffuse(self.ip);
309	                let resume = if ffuse_ip + 1 >= self.program.len() { 0 }
310	                             else { ffuse_ip + 1 };
311	                self.push_fork(resume);
312	                if let Some(frame) = self.fork_top_mut() {
313	                    frame.right_val = v;
314	                    frame.right_set = true;
315	                }
316	                self.stack.push(v);
317	            }
318	            Token::Evalt => {
319	                let v = self.stack.pop();
320	                // ── B-live instrumentation: B on stack when gate fires ──
321	                if v == B4::B { self.b_live_count += 1; }
322	                let filtered = if v == B4::T { B4::T } else { B4::N };
323	                // ── Gate discrimination: T actually passed ──
324	                if v == B4::T { self.gate_discrimination_count += 1; }
325	                self.stack.push(filtered);
326	            }
327	            Token::Evalf => {
328	                let v = self.stack.pop();
329	                // ── B-live instrumentation ──
330	                if v == B4::B { self.b_live_count += 1; }
331	                let filtered = if v == B4::F { B4::F } else { B4::N };
332	                // ── Gate discrimination: F actually passed ──
333	                if v == B4::F { self.gate_discrimination_count += 1; }
334	                self.stack.push(filtered);
335	            }
336	            Token::Ffuse => {
337	                let left = self.stack.pop();
338	                if let Some(frame) = self.pop_fork() {
339	                    let right = if frame.right_set { frame.right_val } else { B4::N };
340	                    self.stack.push(b4_join(left, right));
341	                    next_ip = frame.resume_ip;
342	                } else {
343	                    self.stack.push(left);
344	                }
345	            }
346	            Token::Engagr => {
347	                self.registers.engagr = true;
348	                self.stack.push(B4::B);
349	            }
350	            Token::Ifix => {
351	                let addr = self.registers.read(0) as usize;
352	                let val  = self.stack.pop();
353	                self.memory.write(addr, val);
354	            }
355	            Token::Fsplit3 => {
356	                // 3-way fork (T/F/I arms). In B4 context, same as Fsplit.
357	                let v = self.stack.peek();
358	                let ffuse_ip = self.find_matching_ffuse3(self.ip);
359	                let resume = if ffuse_ip + 1 >= self.program.len() { 0 }
360	                             else { ffuse_ip + 1 };
361	                self.push_fork(resume);
362	                if let Some(frame) = self.fork_top_mut() {
363	                    frame.right_val = v;
364	                    frame.right_set = true;
365	                }
366	                self.stack.push(v);
367	            }
368	            Token::Ffuse3 => {
369	                // 3-way fuse. In B4 context, same as Ffuse.
370	                let left = self.stack.pop();
371	                if let Some(frame) = self.pop_fork() {
372	                    let right = if frame.right_set { frame.right_val } else { B4::N };
373	                    self.stack.push(b4_join(left, right));
374	                    next_ip = frame.resume_ip;
375	                } else {
376	                    self.stack.push(left);
377	                }
378	            }
379	            Token::Evali => {
380	                // Evaluate on Information axis: keep B (both), everything else -> N.
381	                let v = self.stack.pop();
382	                self.stack.push(if v == B4::B { B4::B } else { B4::N });
383	            }
384	            Token::Rotat => {
385	                // ROTAT — the first op-opcode: cyclic shift of the program-ring
386	                // by k, here realized as stack rotation. Pops k (default 1) and
387	                // rotates the remaining stack data by k positions mod depth.
388	                // The ring automorphism: ROTAT^n = identity.
389	                let k_val = self.stack.pop();
390	                let k = (k_val as u8 as usize).max(1);
391	                self.stack.rotate(k);
392	            }
393	        }
394	
395	        self.ip = next_ip;
396	
397	        // ── Write stack-top value into ring buffer (end of ACT) ──
398	        self.value_trace[self.value_trace_head] = self.stack.peek();
399	        self.value_trace_head = (self.value_trace_head + 1) % 16;
400	
401	        // OBSERVE
402	        self.phase = Phase::Observe;
403	        self.frob_checks += 1;
404	        // ── Frobenius harness verification ──
405	        { use crate::frob_verify::{verify_program_structure, verify_frobenius_identity}; 
406	          let _ = self.harness.check(verify_program_structure(&self.program)); 
407	          let v = self.stack.peek(); 
408	          let _ = self.harness.check(verify_frobenius_identity(v)); 
409	          self.frob_checks = self.harness.total(); 
410	          self.frob_open   = self.harness.open_count; }
411	
412	        // UPDATE
413	        self.phase = Phase::Update;
414	        if self.ip >= self.program.len() {
415	            self.ip = 0;
416	            self.try_self_modify();
417	        }
418	
419	        self.phase = Phase::Think;
420	        true
421	    }
422	
423	    /// Run N ticks (tight loop).
424	    pub fn run(&mut self, max_ticks: u64) -> u64 {
425	        let start = self.tick_count;
426	        while !self.halted && (self.tick_count - start) < max_ticks {
427	            self.tick();
428	        }
429	        self.tick_count - start
430	    }
431	
432	    /// Continuous execution. Returns when halted or should_stop() true.
433	    pub fn run_continuous<F: FnMut() -> bool>(&mut self, mut should_stop: F) -> u64 {
434	        let start = self.tick_count;
435	        while !self.halted && !should_stop() {
436	            self.tick();
437	        }
438	        self.tick_count - start
439	    }
440	
441	    /// Run one tick if the timer has fired.
442	    pub fn tick_on_timer(&mut self) -> bool {
443	        if crate::interrupts::timer_ready() {
444	            crate::interrupts::pending_ticks();
445	            self.tick()
446	        } else {
447	            !self.halted
448	        }
449	    }
450	
451	    /// Install `prog` and zero runtime evidence so a subsequent `snapshot`
452	    /// reports the *static* classification of the new program (not the previous
453	    /// program's b_live / winding / stale tier). Without this, VII→XII handoffs
454	    /// (and any `load` before the first tick) left the old snapshot in place.
455	    /// Stack and registers are cleared so leftover B from a prior program cannot
456	    /// fake b_live on the next one.
457	    fn install_program(&mut self, prog: Program) {
458	        self.program = prog;
459	        self.ip = 0;
460	        self.fork_depth = 0;
461	        self.halted = false;
462	        self.phase = Phase::Think;
463	        self.b_live_count = 0;
464	        self.gate_discrimination_count = 0;
465	        self.value_trace = [B4::N; 16];
466	        self.value_trace_head = 0;
467	        self.winding_count = 0;
468	        self.stack.clear();
469	        self.registers.clear();
470	        self.snapshot = Some(self_imscribe(&self.program));
471	    }
472	
473	    pub fn load_canonical(&mut self, idx: usize) {
474	        if let Some(prog) = canonical(idx) {
475	            self.install_program(prog);
476	        }
477	    }
