479	    /// Load the program that deliberately targets O_inf_dag (R2, lateral replicative
480	    /// opening) instead of terminal closure — see `tokens::replicative_opening_loop` for why
481	    /// this specific 4-token cycle avoids both O_∞ paths by construction. Ticking it past its
482	    /// first wrap (4 ticks) is what actually sets `winding_count > 0`; loading alone only
483	    /// gets you the two structural preconditions (atomic_reentry, bifurcation_revisited).
484	    pub fn load_replicative(&mut self) {
485	        self.install_program(crate::tokens::replicative_opening_loop());
486	    }
