536	    fn try_self_modify(&mut self) {
537	        if self.dynamic_mode {
538	            // Derive next program from current IgTuple rather than running a preset.
539	            let snap = self.dynamic_imscribe();
540	            let tuple = crate::imas_ig::IgTuple::from_snapshot(&snap);
541	            let len = crate::sequence::next_seq_len(&snap);
542	            self.program = crate::sequence::build_via_substrate(&tuple, len, snap.self_ref, snap.tier);
543	            self.snapshot = Some(self_imscribe(&self.program));
544	            self.ip = 0;
545	            self.fork_depth = 0;
546	        } else if self.stack.depth() > 200 {
547	            self.program.inject(self.ip, Token::Tanch);
548	            self.snapshot = Some(self_imscribe(&self.program));
549	        }
550	    }
551	
552	    /// Enable dynamic mode: the kernel rebuilds its own sequence from its
553	    /// current IgTuple each time the program wraps. The first sequence is
554	    /// built from the current snapshot (or bootstrap defaults if no snapshot yet).
555	    pub fn load_dynamic(&mut self) {
556	        self.dynamic_mode = true;
557	        let snap = match self.snapshot {
558	            Some(s) => s,
559	            None    => self_imscribe(&self.program),
560	        };
561	        let tuple = crate::imas_ig::IgTuple::from_snapshot(&snap);
562	        let len = crate::sequence::next_seq_len(&snap);
563	        self.program = crate::sequence::build_via_substrate(&tuple, len, snap.self_ref, snap.tier);
564	        self.snapshot = Some(self_imscribe(&self.program));
565	        self.ip = 0;
566	        self.fork_depth = 0;
567	        self.halted = false;
568	        self.phase = Phase::Think;
569	    }
570	
571	    /// Disable dynamic mode; leave the current program in place.
572	    pub fn disable_dynamic(&mut self) {
573	        self.dynamic_mode = false;
574	    }
575	
576	    /// Dynamic imscription: static structural analysis overlaid with
577	    /// runtime accumulator values. Call this instead of self_imscribe()
578	    /// when the kernel has runtime state that should inform the tier.
579	    /// When ⊥ is flipped (arev_hop), the snapshot is read through the mirror:
580	    /// same accumulators, evidence triples exchanged, tier recomputed.
581	    pub fn dynamic_imscribe(&self) -> Snapshot {
582	        let mut snap = self_imscribe(&self.program);
583	        snap.b_live_ticks        = self.b_live_count;
584	        snap.gate_discriminations = self.gate_discrimination_count;
585	        snap.value_period         = compute_value_period(&self.value_trace, self.value_trace_head);
586	        snap.winding_count       = self.winding_count;
587	        snap.tier = compute_tier(&snap);
588	        if self.chirality { snap = snap.mirrored(); }
589	        snap
590	    }
591	
592	    /// AREV as a runtime operation — the door, not the classifier. Toggles ⊥,
593	    /// so the kernel descends to (or returns from) the lateral partner at the
594	    /// same shell: every subsequent dynamic_imscribe reads the R1/R2 evidence
595	    /// triples exchanged. Because the accumulators themselves are untouched,
596	    /// arev_hop∘arev_hop = id on the snapshot, exactly. Returns the new ⊥.
597	    pub fn arev_hop(&mut self) -> bool {
598	        self.chirality = !self.chirality;
599	        self.snapshot = Some(self.dynamic_imscribe());
600	        self.chirality
601	    }
602	}
603	
604	// ─── Self-imscription ─────────────────────────────────────────
605	
606	pub fn self_imscribe(prog: &Program) -> Snapshot {
607	    let sig = signature(prog);
608	    let n = prog.len();
609	
610	    let diversity = {
611	        // Sixteen Token variants: the twelve classical opcodes (0..12) plus the
612	        // extension opcodes Fsplit3, Ffuse3, Evali, Rotat (12..16). A two-arity word
613	        // only ever indexes 0..12, so its diversity is unchanged; a three-arity
614	        // Program reaches the higher slots and must not index out of bounds.
615	        let mut seen = [false; 16];
616	        for t in prog.as_slice() { seen[*t as usize] = true; }
617	        seen.iter().filter(|&&b| b).count()
618	    };
619	
620	    let self_ref = n > 0 && prog.get(0) == prog.get(n - 1);
621	
622	    let fsplit = prog.as_slice().iter().any(|t| *t == Token::Fsplit);
623	    let ffuse  = prog.as_slice().iter().any(|t| *t == Token::Ffuse);
624	    // A genuine three-arity Frobenius opcode makes the coupling functorial (order 3):
625	    // FSPLIT3/FFUSE3 fork and fuse a third (Information) arm. The twelve-mark word
626	    // alphabet cannot emit these — no glyph maps to them (belnap_ring_shor::glyph_to_token)
627	    // — so every word derives here with fo ∈ {0,1,2} exactly as before; only a Program
628	    // carrying the extension opcode directly reaches order 3, which is what ≻ 𐑑 (tot) and
629	    // ≺ 𐑬 (out) read, the two CLINK L9 slots outside the word→tuple image.
630	    let fsplit3 = prog.as_slice().iter().any(|t| *t == Token::Fsplit3);
631	    let ffuse3  = prog.as_slice().iter().any(|t| *t == Token::Ffuse3);
632	    let frob_order = if fsplit3 || ffuse3 {
633	        3
634	    } else {
635	        match (fsplit, ffuse) {
636	            (false, false) => 0,
637	            (true,  false) => 1,
638	            (false, true)  => 2,
639	            (true,  true)  => {
640	                let first_split = prog.as_slice().iter().position(|t| *t == Token::Fsplit).unwrap();
641	                let first_fuse  = prog.as_slice().iter().position(|t| *t == Token::Ffuse).unwrap();
642	                if first_split < first_fuse { 1 } else { 2 }
643	            }
644	        }
645	    };
646	
647	    // ── Dialetheia complete: presence check AND cyclic reachability ──
648	    // Programs are cyclic graphs (end wraps to start). B pushed by ENGAGR
649	    // persists across the cycle boundary and can reach gates on the next
650	    // revolution — so the static scan MUST be cyclic, not a linear
651	    // end-of-program cut, and MUST NOT stop at an intermediate ENGAGR.
652	    // For each ENGAGR, walk forward modulo n for a full period (n-1 steps)
653	    // and require at least one EVALT or EVALF somewhere on that ring.
654	    // (VII_Parakernel: trailing ENGAGR at the wrap sees EVALT/EVALF after
655	    //  wrapping past the opening ENGAGR — correct under cyclic semantics.)
656	    let dialetheia_complete = {
657	        let slice = prog.as_slice();
658	        let has_evalt  = slice.iter().any(|t| *t == Token::Evalt);
659	        let has_evalf  = slice.iter().any(|t| *t == Token::Evalf);
660	        let has_engagr = slice.iter().any(|t| *t == Token::Engagr);
661	
662	        if !has_evalt || !has_evalf || !has_engagr {
663	            false
664	        } else {
665	            let mut all_ok = true;
666	            for (i, &t) in slice.iter().enumerate() {
667	                if t == Token::Engagr {
668	                    let mut found_gate = false;
669	                    // Full cyclic walk — wrap freely; do not break on ENGAGR.
670	                    for offset in 1..n {
671	                        let j = (i + offset) % n;
672	                        if slice[j] == Token::Evalt || slice[j] == Token::Evalf {
673	                            found_gate = true;
674	                            break;
675	                        }
676	                    }
677	                    if !found_gate {
678	                        all_ok = false;
679	                        break;
680	                    }
681	                }
682	            }
683	            all_ok
684	        }
685	    };
686	
687	    let p = period(prog);
688	
689	    // ── R2 structural conditions (atomicity, bifurcation) — static, mirrors
690	    // frob_order/self_ref above. winding_count is dynamic-only (see dynamic_imscribe). ──
691	    // is_fsplit/is_ffuse match both arities, so a single three-arity fork pair also reads
692	    // as the point-like re-entry (one fork, one fuse). A two-arity word is counted exactly
693	    // as before, since it carries no three-arity opcode.
694	    let fsplit_count = prog.as_slice().iter().filter(|t| t.is_brancher()).count();
695	    let ffuse_count  = prog.as_slice().iter().filter(|t| t.is_merger()).count();
696	    let atomic_reentry = fsplit_count == 1 && ffuse_count == 1;
697	    let bifurcation_revisited = atomic_reentry && self_ref;
698	
699	    let mut snap = Snapshot {
700	        frobenius_order: frob_order,
701	        period: p,
702	        sig,
703	        token_diversity: diversity,
704	        self_ref,
705	        dialetheia_complete,
706	        tier: 0,
707	        b_live_ticks: 0,
708	        gate_discriminations: 0,
709	        value_period: 0,
710	        atomic_reentry,
711	        bifurcation_revisited,
712	        winding_count: 0,
713	    };
714	    snap.tier = compute_tier(&snap);
715	    snap
716	}
717	
718	/// Compute ouroboricity tier from snapshot.
719	///
720	/// O_0 — no Frobenius or dialetheia presence.
721	/// O_1 — structural: Frobenius order > 0 OR dialetheia_complete (static).
722	/// O_2 — structural + dynamic: O_1 preconditions met, period >= 2,
723	///       AND gate_discriminations > 0 (gates have actually discriminated).
724	///       Runtime b_live > 0 overrides structural dialetheia_complete.
725	/// O_∞ — two independent paths:
726	///   Path A (dialetheia): effective_dialetheia && self_ref && frob_order > 0
727	///         && period >= 3 && (b_live > 0 || value_period >= 3).
728	///   Path B (value-trace): self_ref && frob_order > 0 && period >= 3
729	///         && value_period >= 3. The value trace itself demonstrates
730	///         aperiodic complexity — emergent O_∞ independent of whether
731	///         B specifically passed a gate.
732	/// O_inf_dag (R2) — LATERAL to O_∞, not above it (tier 4, but a sideways move,
733	///       not a rung — see Snapshot::tier_name). R1 (O_∞, above) is checked
734	///       first and always dominates: this branch is reached only when neither
735	///       Path A nor Path B fired. Fires on the three-part replicative-opening
736	///       signal (atomicity, bifurcation, winding), mirroring the Lean kernel's
737	///       R2 triple dim=dead ∧ top=mime ∧ prot=ah:
738	///         atomic_reentry (a single, point-like FSPLIT/FFUSE pair)
739	///         && bifurcation_revisited (that fork point recurs every wrap)
740	///         && winding_count > 0 (a protected winding has actually occurred)
741	///         && self_ref && frob_order > 0 (same self-referential precondition as R1).
742	fn compute_tier(snap: &Snapshot) -> u8 {
743	    // Runtime evidence: B actually reached a gate → structural dialetheia
744	    // prediction is overridden. The kernel is an exact isomorphism of how
745	    // reality does it — runtime behavior trumps static analysis.
746	    let effective_dialetheia = snap.dialetheia_complete || snap.b_live_ticks > 0;
747	
748	    // Path A: dialetheia-driven O_∞
749	    if effective_dialetheia && snap.self_ref && snap.frobenius_order > 0 {
750	        if snap.period >= 3 && (snap.b_live_ticks > 0 || snap.value_period >= 3) {
751	            return 3;
752	        }
753	        if snap.period >= 2 && snap.gate_discriminations > 0 {
754	            return 2;
755	        }
756	        return 1;
757	    }
758	
759	    // Path B: value-trace-driven O_∞ — the stack-top value trace has
760	    // its own aperiodic signature. Emergent complexity independent of
761	    // whether B specifically reached a gate.
762	    if snap.self_ref && snap.frobenius_order > 0
763	        && snap.period >= 3
764	        && snap.value_period >= 3
765	    {
766	        return 3;
767	    }
768	
769	    // R2: lateral opening, tested only after R1's O_∞ paths (above) have failed.
770	    if snap.self_ref && snap.frobenius_order > 0
771	        && snap.atomic_reentry && snap.bifurcation_revisited && snap.winding_count > 0
772	    {
773	        return 4;
774	    }
775	
776	    if snap.frobenius_order > 0 || snap.dialetheia_complete {
777	        1
778	    } else {
779	        0
780	    }
781	}
782	
783	/// Compute minimal period of the stack-top value trace ring buffer.
784	/// Returns 0 if not enough data to determine a period.
785	fn compute_value_period(trace: &[B4; 16], head: usize) -> usize {
786	    // Look at the ring buffer as if head points to the next write slot.
787	    // The most recent value is at (head + 15) % 16.
788	    // Try periods from 1..=16.
789	    for p in 1..=16 {
790	        let mut periodic = true;
791	        for i in 0..(16 - p) {
792	            let a = trace[(head + 16 - 1 - i) % 16];
793	            let b = trace[(head + 16 - 1 - i - p) % 16];
794	            if a != b {
795	                periodic = false;
796	                break;
797	            }
798	        }
799	        if periodic {
800	            return p;
801	        }
802	    }
803	    0 // not yet known / aperiodic
804	}
