1	//! IMASM-16_3 — the 14-opcode, purely-symbolic trilattice extension of the classic
2	//! 12-opcode IMASM grammar (`imasm.rs`), for the real trilattice SIXTEEN_3:
3	//! Shramko, Dunn & Takenaka, "The Trilattice of Constructive Truth Values",
4	//! J. Logic and Computation 11(6):761-788, 2001 — verified against the source PDF.
5	//!
6	//! THE REAL CONSTRUCTION (§5 of the paper). The base set is four initial truth
7	//! values, not two and not a product of two FOURs:
8	//!
9	//! ```text
10	//!     I = {T, F, t, f}
11	//!       T — a sentence is constructively PROVEN
12	//!       F — a sentence is constructively REFUTED
13	//!       t — a sentence is (non-constructively) ACCEPTABLE
14	//!       f — a sentence is (non-constructively) REJECTABLE
15	//! ```
16	//!
17	//! SIXTEEN_3 is the full powerset P(I) — all 16 subsets of these four base
18	//! values (N = {} = empty, A = {T,F,t,f} = full). Three orderings (Def. 5.2):
19	//!
20	//! ```text
21	//!     x ≤_i y  ⟺  x ⊆ y                                        (information)
22	//!     x ≤_t y  ⟺  x∩{T,t} ⊆ y∩{T,t}  and  y∩{F,f} ⊆ x∩{F,f}     (truth)
23	//!     x ≤_c y  ⟺  x∩{T,F} ⊆ y∩{T,F}  and  y∩{t,f} ⊆ x∩{t,f}     (constructivity)
24	//! ```
25	//!
26	//! Verified against the paper's own worked example: T ∧ t = N under ≤_t (the
27	//! conjunction of two "truths" gives nothing) — `meet_t` below reproduces this
28	//! exactly, checked by a unit test.
29	//!
30	//! Register: a real 4-bit subset of {T, F, t, f} (16 states, matching the
31	//! paper's carrier exactly). Opcode → base-value mapping:
32	//!
33	//! ```text
34	//!     EVALT sets T (constructive truth touched)
35	//!     EVALF sets F (constructive falsity touched)
36	//!     EVALI sets BOTH t and f (the acceptable/rejectable pair IS the
37	//!           information layer beyond classical T/F)
38	//!     AREV  the reverse morphism, T↔F and t↔f together (bilattice negation:
39	//!           inverts ≤_t, leaves ≤_i exactly — a swap preserves |x|). It factors
40	//!           internally into a per-layer swap each, but those factors are not
41	//!           opcodes; the retired marks ~ ≁ once named them and ⊡ IFIX replaces
42	//!           them, so the printed set is twelve.
43	//! ```
44	//!
45	//! A sibling module, not a replacement: FSPLIT3/FFUSE3 (3-way fork/fuse) sit
46	//! alongside FSPLIT/FFUSE — `imasm.rs`'s ancestry-pairing graph engine and the
47	//! Lean `.prod` scaffold generator are untouched. No opcode glyph is a Latin
48	//! letter, so a trilattice verdict (T, N, B, F) can never be confused with a
49	//! graph node.
50	
51	use core::fmt::Write as _;
52	
53	use alloc::format;
54	use alloc::string::{String, ToString};
55	use alloc::vec::Vec;
56	
57	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
58	pub enum Token16_3 {
59	    Vinit,   // ⊢  0→1  source boundary
60	    Tanch,   // ⊣  1→1  sink boundary
61	    Afwd,    // >  1→1  forward morphism, WORK
62	    Arev,    // <  1→1  reverse morphism, WORK
63	    Clink,   // ⋈  1→1  composition / relational link, WORK
64	    Imscrib, // ⊙  1→1  identity / neutral self-reference
65	    Fsplit3, // ∈  1→3  3-way split: T, F, I arms
66	    Ffuse3,  // ∋  3→1  3-way fuse: merges T, F, I arms
67	    Evalt,   // ⊤  1→1  evaluates the True axis (≤_t), WORK
68	    Evalf,   // ⊥  1→1  evaluates the False axis (≤_t), WORK
69	    Evali,   // ⊞  1→1  evaluates the Information axis (≤_i), WORK
70	    Ifix,    // ⊡  1→1  irreversible commit, WORK
71	}
72	
73	use Token16_3::*;
74	
75	// THE set is twelve. AREV `<` is the whole reverse morphism; the two-layer swaps
76	// it factors into (once mis-spelled ~ TNEG / ≁ INEG) are internal to `<`, never
77	// opcodes — ⊡ IFIX replaces those retired marks. ROTAT ↺/↻ is the op-opcode that
78	// acts ON a word, not a token in it.
79	pub const ALL_TOKENS: [Token16_3; 12] = [
80	    Vinit, Tanch, Afwd, Arev, Clink, Imscrib, Fsplit3, Ffuse3,
81	    Evalt, Evalf, Evali, Ifix,
82	];
83	
84	impl Token16_3 {
85	    pub fn glyph(self) -> char {
86	        match self {
87	            Vinit => '⊢', Tanch => '⊣', Afwd => '≻', Arev => '≺', Clink => '⋈',
88	            Imscrib => '⊙', Fsplit3 => '∈', Ffuse3 => '∋', Evalt => '⊤',
89	            Evalf => '⊥', Evali => '⊞', Ifix => '⊡',
90	        }
91	    }
92	
93	    pub fn name(self) -> &'static str {
94	        match self {
95	            Vinit => "VINIT", Tanch => "TANCH", Afwd => "AFWD", Arev => "AREV",
96	            Clink => "CLINK", Imscrib => "IMSCRIB", Fsplit3 => "FSPLIT3",
97	            Ffuse3 => "FFUSE3", Evalt => "EVALT", Evalf => "EVALF",
98	            Evali => "EVALI", Ifix => "IFIX",
99	        }
100	    }
101	
102	    pub fn is_work(self) -> bool {
103	        matches!(self, Afwd | Arev | Clink | Evalt | Evalf | Evali | Ifix)
104	    }
105	
106	    fn from_glyph(c: char) -> Option<Token16_3> {
107	        // Only the twelve glyphs are tokens. The old marks ◇ ● ☊ ☋ = ═ + × ¬ ~ ≁
108	        // are NOT IMASM tokens and do not parse — no alias, no shim; a word that
109	        // contains one reads it as nothing (N / void), exactly as a stray letter
110	        // does. A retired form that still loaded is how legacy notation survives a
111	        // purge, so there is none.
112	        ALL_TOKENS.iter().copied().find(|t| t.glyph() == c)
113	    }
114	}
115	
116	pub fn parse_glyph_word(word: &str) -> Vec<Token16_3> {
117	    word.chars().filter_map(Token16_3::from_glyph).collect()
118	}
119	
120	/// Register: a real subset of the 4-element base {T, F, t, f} — 16 states,
121	/// the actual Shramko-Wansing SIXTEEN_3 carrier (not an approximation).
122	#[derive(Clone, Copy, Default, PartialEq, Eq)]
123	pub struct Reg16_3 {
124	    pub big_t: bool,   // T — constructively proven
125	    pub big_f: bool,   // F — constructively refuted
126	    pub small_t: bool, // t — acceptable (non-constructive truth)
127	    pub small_f: bool, // f — rejectable (non-constructive falsity)
128	}
129	
130	impl Reg16_3 {
131	    pub fn name(self) -> String {
132	        if !self.big_t && !self.big_f && !self.small_t && !self.small_f {
133	            return "N".to_string();
134	        }
135	        if self.big_t && self.big_f && self.small_t && self.small_f {
136	            return "A".to_string();
137	        }
138	        let mut s = String::new();
139	        if self.big_t { s.push('T'); }
140	        if self.big_f { s.push('F'); }
141	        if self.small_t { s.push('t'); }
142	        if self.small_f { s.push('f'); }
143	        s
144	    }
145	
146	    /// The glyph face: occupancy of {T, F, t, f} drawn as quadrant ink —
147	    /// T upper-left, F upper-right, t lower-left, f lower-right. The glyph
148	    /// IS the subset (meet/join of states = intersection/union of ink);
149	    /// N renders as ░, the unmarked field, never as absence. No Latin,
150	    /// matching the opcode face's rule.
151	    pub fn glyph(self) -> char {
152	        match (self.big_t, self.big_f, self.small_t, self.small_f) {
153	            (false, false, false, false) => '░',
154	            (true,  false, false, false) => '▘',
155	            (false, true,  false, false) => '▝',
156	            (false, false, true,  false) => '▖',
157	            (false, false, false, true ) => '▗',
158	            (true,  true,  false, false) => '▀',
159	            (true,  false, true,  false) => '▌',
160	            (true,  false, false, true ) => '▚',
161	            (false, true,  true,  false) => '▞',
162	            (false, true,  false, true ) => '▐',
163	            (false, false, true,  true ) => '▄',
164	            (true,  true,  true,  false) => '▛',
165	            (true,  true,  false, true ) => '▜',
166	            (true,  false, true,  true ) => '▙',
167	            (false, true,  true,  true ) => '▟',
168	            (true,  true,  true,  true ) => '█',
169	        }
170	    }
171	
172	    pub fn union(self, o: Reg16_3) -> Reg16_3 {
173	        Reg16_3 {
174	            big_t: self.big_t || o.big_t, big_f: self.big_f || o.big_f,
175	            small_t: self.small_t || o.small_t, small_f: self.small_f || o.small_f,
176	        }
177	    }
178	
179	    /// The truth part x ∩ {T, t} — what EVALT passes, and the first δ arm.
180	    pub fn truth_part(self) -> Reg16_3 {
181	        Reg16_3 { big_t: self.big_t, small_t: self.small_t, ..Reg16_3::default() }
182	    }
183	
184	    /// The falsity part x ∩ {F, f} — what EVALF passes, and the second δ arm.
185	    pub fn falsity_part(self) -> Reg16_3 {
186	        Reg16_3 { big_f: self.big_f, small_f: self.small_f, ..Reg16_3::default() }
187	    }
188	
189	    /// The constructive part x ∩ {T, F} — the two arms δ separates when it fans
190	    /// at arity 3, where the truth cut is taken inside the constructive block.
191	    pub fn constructive_part(self) -> Reg16_3 {
192	        Reg16_3 { big_t: self.big_t, big_f: self.big_f, ..Reg16_3::default() }
193	    }
194	
195	    /// The information part x ∩ {t, f} — the third δ arm, and what EVALI sets.
196	    ///
197	    /// It is one arm rather than two because ⊞ sets t and f together, so the
198	    /// non-constructive pair can only ever be entered as a block. That is where
199	    /// the arity of the fork comes from: not a choice, but the gate set.
200	    pub fn info_part(self) -> Reg16_3 {
201	        Reg16_3 { small_t: self.small_t, small_f: self.small_f, ..Reg16_3::default() }
202	    }
203	
204	    /// The constructive swap T ↔ F, leaving the information layer alone.
205	    ///
206	    /// This and `info_swap` are the two factors of the involution: they act on
207	    /// disjoint bits, so they commute, and composing them IS `invol`. AREV is not
208	    /// a third operation beside them, it is both at once, which is why the
209	    /// classical slice needs only one of them: with t and f absent `info_swap` is
210	    /// the identity and AREV is `truth_swap`.
211	    pub fn truth_swap(self) -> Reg16_3 {
212	        Reg16_3 { big_t: self.big_f, big_f: self.big_t, ..self }
213	    }
214	
215	    /// The information swap t ↔ f, leaving the constructive layer alone.
216	    pub fn info_swap(self) -> Reg16_3 {
217	        Reg16_3 { small_t: self.small_f, small_f: self.small_t, ..self }
218	    }
219	
220	    /// The involution T ↔ F, t ↔ f — the reverse morphism AREV's action on
221	    /// values (both layer-swaps at once; ⊆-monotone, its own inverse).
222	    pub fn invol(self) -> Reg16_3 {
223	        Reg16_3 { big_t: self.big_f, big_f: self.big_t, small_t: self.small_f, small_f: self.small_t }
224	    }
225	
226	    /// FOUR sits inside SIXTEEN_3 as the classical pair {T, F}: N={}, T={T},
227	    /// F={F}, B={T,F}. Render this value as its FOUR name when it lives in that
228	    /// slice; a value touching t/f has left the slice and keeps its 16_3 name.
229	    pub fn four_name(self) -> String {
230	        if self.small_t || self.small_f {
231	            return self.name();
232	        }
233	        match (self.big_t, self.big_f) {
234	            (false, false) => "N".into(),
235	            (true, false) => "T".into(),
236	            (false, true) => "F".into(),
237	            (true, true) => "B".into(),
238	        }
239	    }
240	
241	    /// The FOUR slice's glyph face: ░/▘/▝/▀ for N/T/F/B per `glyph()` — B of
242	    /// FOUR IS the state {T,F}, so it wears TF's ink; there is no separate
243	    /// verdict alphabet and no Latin anywhere. Values touching t/f have left
244	    /// the slice and keep their 16_3 glyph.
245	    pub fn four_glyph(self) -> char {
246	        self.glyph()
247	    }
248	
249	    /// Parse a register from its name — "N", "A", or any combination of
250	    /// T/F/t/f (order-insensitive), e.g. "Tf" or "tF". The inverse of `name()`.
251	    pub fn from_name(s: &str) -> Option<Reg16_3> {
252	        if s == "N" { return Some(Reg16_3::default()); }
253	        if s == "A" {
254	            return Some(Reg16_3 { big_t: true, big_f: true, small_t: true, small_f: true });
255	        }
256	        let mut r = Reg16_3::default();
257	        for c in s.chars() {
258	            match c {
259	                'T' => r.big_t = true,
260	                'F' => r.big_f = true,
261	                't' => r.small_t = true,
262	                'f' => r.small_f = true,
263	                _ => return None,
264	            }
265	        }
266	        Some(r)
267	    }
268	}
269	
270	// ── The three orderings (Definition 5.2) — kept as free functions since
271	// they're part of the trilattice's public algebra, not just machine internals.
272	
273	/// Information order: x ≤_i y ⟺ x ⊆ y.
274	pub fn leq_i(x: Reg16_3, y: Reg16_3) -> bool {
275	    (!x.big_t || y.big_t) && (!x.big_f || y.big_f) && (!x.small_t || y.small_t) && (!x.small_f || y.small_f)
276	}
277	
278	/// Truth order: positive part (T,t) grows, negative part (F,f) shrinks.
279	pub fn leq_t(x: Reg16_3, y: Reg16_3) -> bool {
280	    let pos_ok = (!x.big_t || y.big_t) && (!x.small_t || y.small_t);
281	    let neg_ok = (!y.big_f || x.big_f) && (!y.small_f || x.small_f);
282	    pos_ok && neg_ok
283	}
284	
285	/// Constructivity order: constructive part (T,F) grows, non-constructive part (t,f) shrinks.
286	pub fn leq_c(x: Reg16_3, y: Reg16_3) -> bool {
287	    let con_ok = (!x.big_t || y.big_t) && (!x.big_f || y.big_f);
288	    let noncon_ok = (!y.small_t || x.small_t) && (!y.small_f || x.small_f);
289	    con_ok && noncon_ok
290	}
291	
292	/// Meet under ≤_t: positive part intersects, negative part unions. Verified
293	/// against the paper's own worked example, T ∧ t = N (§5, p.776-777) — see
294	/// the unit test `meet_t_matches_paper_example`.
295	pub fn meet_t(x: Reg16_3, y: Reg16_3) -> Reg16_3 {
296	    Reg16_3 {
297	        big_t: x.big_t && y.big_t, small_t: x.small_t && y.small_t,
298	        big_f: x.big_f || y.big_f, small_f: x.small_f || y.small_f,
299	    }
300	}
301	
302	pub fn join_t(x: Reg16_3, y: Reg16_3) -> Reg16_3 {
303	    Reg16_3 {
304	        big_t: x.big_t || y.big_t, small_t: x.small_t || y.small_t,
305	        big_f: x.big_f && y.big_f, small_f: x.small_f && y.small_f,
306	    }
307	}
308	
309	pub fn meet_c(x: Reg16_3, y: Reg16_3) -> Reg16_3 {
310	    Reg16_3 {
311	        big_t: x.big_t && y.big_t, big_f: x.big_f && y.big_f,
312	        small_t: x.small_t || y.small_t, small_f: x.small_f || y.small_f,
313	    }
314	}
315	
316	pub fn join_c(x: Reg16_3, y: Reg16_3) -> Reg16_3 {
317	    Reg16_3 {
318	        big_t: x.big_t || y.big_t, big_f: x.big_f || y.big_f,
319	        small_t: x.small_t && y.small_t, small_f: x.small_f && y.small_f,
320	    }
321	}
322	
323	#[derive(Clone, Copy, PartialEq, Eq)]
324	enum Axis { T, F, I }
325	
326	struct Machine {
327	    reg: Reg16_3,
328	    fixed: bool,
329	    /// Fork state is a STACK, not a flag. Fsplit3 pushes a frame, Ffuse3 pops one
330	    /// and folds its touches into the register AND into the enclosing frame, so
331	    /// nested regions compose: an inner apex refines the outer one and μ∘δ=id at
332	    /// each level composes to μ∘δ=id overall.
333	    split_stack: Vec<Vec<Axis>>,
334	}
335	
336	impl Machine {
337	    fn new() -> Self {
338	        Self { reg: Reg16_3::default(), fixed: false, split_stack: Vec::new() }
339	    }
340	
341	    fn touch(&mut self, set: Reg16_3, a: Axis) {
342	        self.reg = self.reg.union(set);
343	        if let Some(frame) = self.split_stack.last_mut() {
344	            if !frame.contains(&a) { frame.push(a); }
345	        }
346	    }
347	
348	    fn step(&mut self, tok: Token16_3) {
349	        if self.fixed && tok != Ifix && tok != Imscrib {
350	            return;
351	        }
352	        let none = Reg16_3::default();
353	        match tok {
354	            Vinit => {
355	                self.reg = none;
356	                self.split_stack.clear();
357	            }
358	            Tanch => {}
359	            Afwd => {
360	                if self.reg == none { self.reg.big_t = true; }
361	            }
362	            Arev => {
363	                // Reverse morphism: clears the register, but does NOT close the
364	                // fork. Only Fsplit3 opens a split context and only Ffuse3 closes
365	                // one; an Arev between two arms is work on an arm, not a fuse.
366	                // Clearing in_split/split_touched here (the body was identical to
367	                // Vinit's) discarded every touch the arms had accumulated, so a
368	                // downstream Ffuse3 folded an empty set.
369	                self.reg = none;
370	            }
371	            Clink => {}
372	            Imscrib => {
373	                if self.reg == none { self.reg.big_t = true; }
374	            }
375	            Fsplit3 => {
376	                self.split_stack.push(Vec::new());
377	            }
378	            Ffuse3 => {
379	                if let Some(closed) = self.split_stack.pop() {
380	                    for a in &closed {
381	                        match a {
382	                            Axis::T => self.reg.big_t = true,
383	                            Axis::F => self.reg.big_f = true,
384	                            Axis::I => { self.reg.small_t = true; self.reg.small_f = true; }
385	                        }
386	                    }
387	                    // Fold the inner apex into the enclosing fork: the outer ∋
388	                    // must see what its sub-regions reconnected.
389	                    if let Some(parent) = self.split_stack.last_mut() {
390	                        for a in closed {
391	                            if !parent.contains(&a) { parent.push(a); }
392	                        }
393	                    }
394	                }
395	            }
396	            Evalt => self.touch(Reg16_3 { big_t: true, ..none }, Axis::T),
397	            Evalf => self.touch(Reg16_3 { big_f: true, ..none }, Axis::F),
398	            Evali => self.touch(Reg16_3 { small_t: true, small_f: true, ..none }, Axis::I),
399	            Ifix => { self.fixed = true; }
400	        }
401	    }
402	}
403	
404	/// Tri-ancestral close condition, the arity-3 generalization of the classic
405	/// `imasm check`'s ancestry rule:
406	///   T — every FSPLIT3 pairs with a later FFUSE3, and at least one work
407	///       opcode ran somewhere inside that interval (a real transformation).
408	///   N — paired, but no work ran inside — μ∘δ=id verifies nothing (identity).
409	///   B — a FSPLIT3 has no matching later FFUSE3 — a fork left open.
410	///   F — a FFUSE3 has no preceding FSPLIT3 — ill-typed.
411	/// Run a word and return the final register's name — the parity handle the
412	/// Python kernel is diffed against (see `tests/python_parity.rs`).
413	pub fn run_word_register(steps: &[Token16_3]) -> String {
414	    let mut m = Machine::new();
415	    for &t in steps { m.step(t); }
416	    m.reg.name()
417	}
418	
419	/// Pair FSPLIT3→FFUSE3 over the word read as a LOOP.
420	///
421	/// A word is a cycle and ROTAT is the cyclic shift (Weyl–Heisenberg X), so a
422	/// rotation that cuts through a region's interior must not change the verdict.
423	/// Pairing over the linearized slice makes it change: the ∋ of a cut region
424	/// lands ahead of its ∈ and reads as ill-typed while the region is intact.
425	/// Returns pairs `(si, fj)` with the region running forward around the cycle,
426	/// or `None` on a true count imbalance that no rotation can repair.
427	fn cyclic_pairs(steps: &[Token16_3]) -> Option<Vec<(usize, usize)>> {
428	    let n = steps.len();
429	    let splits: Vec<usize> = steps.iter().enumerate().filter(|(_, t)| **t == Fsplit3).map(|(i, _)| i).collect();
430	    let fuses: Vec<usize> = steps.iter().enumerate().filter(|(_, t)| **t == Ffuse3).map(|(i, _)| i).collect();
431	    if splits.is_empty() && fuses.is_empty() { return Some(Vec::new()); }
432	    if splits.len() != fuses.len() { return None; }
433	    // By the cycle lemma some start at a ∈ pairs every region without underflow.
434	    for &start in &splits {
435	        let mut stack: Vec<usize> = Vec::new();
436	        let mut pairs: Vec<(usize, usize)> = Vec::new();
437	        let mut ok = true;
438	        for off in 0..n {
439	            let i = (start + off) % n;
440	            if steps[i] == Fsplit3 {
441	                stack.push(i);
442	            } else if steps[i] == Ffuse3 {
443	                match stack.pop() {
444	                    Some(si) => pairs.push((si, i)),
445	                    None => { ok = false; break; }
446	                }
447	            }
448	        }
449	        if ok && stack.is_empty() { return Some(pairs); }
450	    }
451	    None
452	}
453	
454	/// Tokens strictly inside the region, walking forward around the cycle.
455	fn cyclic_interior(steps: &[Token16_3], si: usize, fj: usize) -> Vec<Token16_3> {
456	    let n = steps.len();
457	    let span = (fj + n - si) % n;
458	    (1..span).map(|j| steps[(si + j) % n]).collect()
459	}
460	
461	/// Tri-ancestral close condition, the arity-3 generalization of the classic
462	/// `imasm check`'s ancestry rule. Pairing is CYCLIC (see `cyclic_pairs`):
463	///   T — every FSPLIT3 pairs with a FFUSE3 around the cycle, and at least one
464	///       work opcode ran inside that region (a real transformation).
465	///   N — paired, but no work ran inside — μ∘δ=id verifies nothing (identity).
466	///   B — a FSPLIT3 has no FFUSE3 to pair with — a fork left open.
467	///   F — a FFUSE3 has no FSPLIT3 to pair with — ill-typed.
468	pub fn tri_ancestral_verdict(steps: &[Token16_3]) -> (char, String) {
469	    let splits: Vec<usize> = steps.iter().enumerate().filter(|(_, t)| **t == Fsplit3).map(|(i, _)| i).collect();
470	    let fuses: Vec<usize> = steps.iter().enumerate().filter(|(_, t)| **t == Ffuse3).map(|(i, _)| i).collect();
471	
472	    match cyclic_pairs(steps) {
473	        None => {
474	            if fuses.len() > splits.len() {
475	                ('F', format!("FFUSE3 at step {} has no FSPLIT3 to pair — ill-typed", fuses[0] + 1))
476	            } else {
477	                ('B', format!("FSPLIT3 at step {} dangles — no matching FFUSE3", splits[0] + 1))
478	            }
479	        }
480	        Some(pairs) => {
481	            if pairs.is_empty() {
482	                return ('N', "No fork/fuse — void, never weighed alternatives".to_string());
483	            }
484	            for (si, fj) in pairs {
485	                if cyclic_interior(steps, si, fj).iter().any(|t| t.is_work()) {
486	                    return ('T', "Tri-ancestral reconnection over a transformed object — closes".to_string());
487	                }
488	            }
489	            ('N', "Split/fused with no work on any arm — μ∘δ=id verifies nothing".to_string())
490	        }
491	    }
492	}
493	
494	fn run_trace(steps: &[Token16_3]) -> String {
495	    let mut mach = Machine::new();
496	    let mut out = String::new();
497	    let _ = writeln!(out, "  {:>3} {:^5} {:<9} {:>5} → {:>5}", "Step", "Glyph", "Token", "Reg↓", "Reg↑");
498	    let start = mach.reg;
499	    for (idx, &tok) in steps.iter().enumerate() {
500	        let before = mach.reg.name();
501	        mach.step(tok);
502	        let after = mach.reg.name();
503	        let _ = writeln!(out, "  {:>3} {:^5} {:<9} {:>5} → {:>5}", idx + 1, tok.glyph(), tok.name(), before, after);
504	    }
505	    let closed = mach.reg == start;
506	    let (verdict, msg) = tri_ancestral_verdict(steps);
507	    let _ = writeln!(out);
508	    let _ = writeln!(out, "  Closed walk: {closed}");
509	    let _ = writeln!(out, "  Final register: {}", mach.reg.name());
510	    let _ = writeln!(out, "  Tri-ancestral verdict: {verdict} — {msg}");
511	    out
512	}
513	
514	pub fn run(args: &[String]) -> String {
515	    let Some(op) = args.first() else {
516	        return "imasm16_3 <op> …; op ∈ check|ref|algebra — the 12-opcode SIXTEEN_3 trilattice grammar.\n\
517	                `check <glyph_word>` runs the register machine and type-checks tri-ancestral closure.\n\
518	                `ref` lists the 12 opcodes.\n\
519	                `algebra <op> A B` runs a trilattice lattice operation on two register values (named\n\
520	                  N, A, or any of T/F/t/f, e.g. `algebra meet_t T t`); op ∈ leq_i|leq_t|leq_c|meet_t|join_t|meet_c|join_c.\n".to_string();
521	    };
522	    match op.as_str() {
523	        "algebra" => {
524	            let (Some(sub), Some(a_name), Some(b_name)) = (args.get(1), args.get(2), args.get(3)) else {
525	                return "imasm16_3 algebra <op> A B; op ∈ leq_i|leq_t|leq_c|meet_t|join_t|meet_c|join_c; \
526	                        A, B ∈ {N, A, or any combination of T/F/t/f}.\n".to_string();
527	            };
528	            let (Some(a), Some(b)) = (Reg16_3::from_name(a_name), Reg16_3::from_name(b_name)) else {
529	                return format!("imasm16_3 algebra: could not parse '{a_name}' or '{b_name}' — use N, A, or T/F/t/f.\n");
530	            };
531	            match sub.as_str() {
532	                "leq_i" => format!("{} ≤_i {} : {}\n", a.name(), b.name(), leq_i(a, b)),
533	                "leq_t" => format!("{} ≤_t {} : {}\n", a.name(), b.name(), leq_t(a, b)),
534	                "leq_c" => format!("{} ≤_c {} : {}\n", a.name(), b.name(), leq_c(a, b)),
535	                "meet_t" => format!("{} ∧ {} = {}\n", a.name(), b.name(), meet_t(a, b).name()),
536	                "join_t" => format!("{} ∨ {} = {}\n", a.name(), b.name(), join_t(a, b).name()),
537	                "meet_c" => format!("{} △ {} = {}\n", a.name(), b.name(), meet_c(a, b).name()),
538	                "join_c" => format!("{} ▽ {} = {}\n", a.name(), b.name(), join_c(a, b).name()),
539	                other => format!("imasm16_3 algebra: unknown op '{other}'; op ∈ leq_i|leq_t|leq_c|meet_t|join_t|meet_c|join_c\n"),
540	            }
541	        }
542	        "ref" => {
543	            let mut out = String::from("IMASM-16_3 — 12 symbolic opcodes (SIXTEEN_3 = P({T,F,t,f}), Shramko/Dunn/Takenaka 2001):\n");
544	            for t in ALL_TOKENS {
545	                let _ = writeln!(out, "  {}  {:<9} {}", t.glyph(), t.name(), if t.is_work() { "WORK" } else { "no-op (structural)" });
546	            }
547	            let _ = writeln!(out, "  ↺/↻ ROTAT     op-opcode: the cyclic shift (Weyl-Heisenberg X) on the WHOLE word, not a token in it");
548	            let _ = writeln!(out, "  (the marks ◇ ● = + × ¬ ~ ≁ are NOT tokens and do not parse — no alias; they read as nothing)");
549	            out
550	        }
551	        "check" => {
552	            let Some(word) = args.get(1) else {
553	                return "imasm16_3 check <glyph_word>; e.g. imasm16_3 check ⊢>∈⊤⊥⊞∋⊡⊣\n".to_string();
554	            };
555	            let steps = parse_glyph_word(word);
556	            if steps.is_empty() {
557	                return format!("imasm16_3 check: no recognized IMASM-16_3 glyphs in '{word}'\n");
558	            }
559	            format!("Word: {}\n{}", steps.iter().map(|t| t.glyph()).collect::<String>(), run_trace(&steps))
560	        }
561	        other => format!("imasm16_3: unknown op '{other}'; op ∈ check|ref\n"),
562	    }
563	}
564	
565	#[cfg(test)]
566	mod tests {
567	    use super::*;
568	
569	    #[test]
570	    fn example_word_closes_with_work() {
571	        // Legal-alphabet tri word: fork, work on the arms, fuse, latch.
572	        let steps = parse_glyph_word("⊢>∈⊤⊥⊞∋⊡⊣");
573	        assert_eq!(steps.len(), 9);
574	        let (verdict, _) = tri_ancestral_verdict(&steps);
575	        assert_eq!(verdict, 'T');
576	    }
577	
578	    #[test]
579	    fn retired_marks_do_not_parse() {
580	        // ◇ ● = + × ¬ ~ ≁ (and ═ ☊ ☋) are not IMASM tokens: they do not parse,
581	        // they are not aliased to anything, and a word of only them is empty.
582	        for m in ["~", "≁", "¬", "◇", "●", "=", "+", "×", "═", "☊", "☋"] {
583	            assert!(parse_glyph_word(m).is_empty(), "retired mark {m} still parses");
584	        }
585	        // Interspersed in a real word they are simply skipped (read as nothing).
586	        assert_eq!(parse_glyph_word("⊢∈~⊤≁∋⊡⊣"), parse_glyph_word("⊢∈⊤∋⊡⊣"));
587	    }
588	
589	    #[test]
590	    fn verdict_is_rotat_invariant() {
591	        // ROTAT is the cyclic shift, so every rotation is the same object and
592	        // must return the same verdict. Linear pairing gave T,T,F,F,F,F,F,F,F,T,T,T.
593	        let base: Vec<char> = "⊢∈⋈<>⊤⊥⊞∋⊙⊡⊣".chars().collect();
594	        let n = base.len();
595	        for k in 0..n {
596	            let rot: String = (0..n).map(|i| base[(i + k) % n]).collect();
597	            let steps = parse_glyph_word(&rot);
598	            let (verdict, _) = tri_ancestral_verdict(&steps);
599	            assert_eq!(verdict, 'T', "rotation k={k} gave {verdict} for {rot}");
600	        }
601	    }
602	
603	    #[test]
604	    fn arev_does_not_close_the_fork() {
605	        // AREV is work on an arm, not a fuse. Its body used to be identical to
606	        // VINIT's, which discarded the arms' touches so ∋ folded an empty set.
607	        let steps = parse_glyph_word("⊢∈⊤⋈⊥<>⊞∋⊙⊡⊣");
608	        let mut m = Machine::new();
609	        for &t in &steps { m.step(t); }
610	        assert_eq!(m.reg.name(), "A", "the three arms must all reach the apex");
611	    }
612	
613	    #[test]
614	    fn nested_forks_compose() {
615	        // Fork state is a stack: an inner ∋ must not close the enclosing fork.
616	        // With in_split as a bool the outer region lost every touch after the
617	        // first inner fuse and landed on Ftf instead of the top.
618	        let steps = parse_glyph_word("⊢⊙⋈∈∈>⊤<∋∈⊥<∋⊞∋⋈⊙⊡⊣");
619	        let mut m = Machine::new();
620	        for &t in &steps { m.step(t); }
621	        assert_eq!(m.reg.name(), "A", "nested apexes must fold into the outer fork");
622	    }
623	
624	    #[test]
625	    fn cross_repo_parity_word() {
626	        let steps = parse_glyph_word("⊢>>⋈∈⊤⊡∋<⊡⊣");
627	        let (verdict, _) = tri_ancestral_verdict(&steps);
628	        assert_eq!(verdict, 'T');
629	    }
630	
631	    #[test]
632	    fn neutral_inflation_is_identity_not_error() {
633	        let steps = parse_glyph_word("⊢∈⊙⊙⊙∋⊣");
634	        let (verdict, _) = tri_ancestral_verdict(&steps);
635	        assert_eq!(verdict, 'N');
636	    }
637	
638	    #[test]
639	    fn dangling_split_is_b() {
640	        let steps = parse_glyph_word("⊢∈⊤⊣");
641	        let (verdict, _) = tri_ancestral_verdict(&steps);
642	        assert_eq!(verdict, 'B');
643	    }
644	
645	    #[test]
646	    fn fuse_without_split_is_f() {
647	        let steps = parse_glyph_word("⊢⊤∋⊣");
648	        let (verdict, _) = tri_ancestral_verdict(&steps);
649	        assert_eq!(verdict, 'F');
650	    }
651	
652	    #[test]
653	    fn all_12_opcodes_have_distinct_glyphs() {
654	        let glyphs: std::collections::HashSet<char> = ALL_TOKENS.iter().map(|t| t.glyph()).collect();
655	        assert_eq!(glyphs.len(), 12);
656	        for g in &glyphs {
657	            assert!(!g.is_ascii_alphabetic(), "opcode glyph {g} is a Latin letter");
658	        }
659	    }
660	
661	    /// The paper's own worked example (§5, p.776-777): "T ∧ t = N" — the
662	    /// conjunction of two truths gives nothing, because neither conjunct is
663	    /// BOTH T and t simultaneously.
664	    #[test]
665	    fn meet_t_matches_paper_example() {
666	        let big_t_only = Reg16_3 { big_t: true, ..Default::default() };
667	        let small_t_only = Reg16_3 { small_t: true, ..Default::default() };
668	        let result = meet_t(big_t_only, small_t_only);
669	        assert_eq!(result.name(), "N");
670	    }
671	
672	    #[test]
673	    fn negation_preserves_information_order() {
674	        // A defining property of trilattice negation: it must leave ≤_i
675	        // (the subset/information order) unchanged. Swapping T↔F preserves
676	        // popcount, hence preserves ⊆-comparisons against any fixed y.
677	        let x = Reg16_3 { big_t: true, small_t: true, ..Default::default() };
678	        let mut neg_x = x;
679	        std::mem::swap(&mut neg_x.big_t, &mut neg_x.big_f);
680	        // |x| == |neg_x|, and both are still comparable to N and A the same way.
681	        assert_eq!(leq_i(Reg16_3::default(), x), leq_i(Reg16_3::default(), neg_x));
682	        assert_eq!(leq_i(x, Reg16_3 { big_t: true, big_f: true, small_t: true, small_f: true }),
683	                   leq_i(neg_x, Reg16_3 { big_t: true, big_f: true, small_t: true, small_f: true }));
684	    }
685	
686	    #[test]
687	    fn sixteen_states_reachable() {
688	        // The full carrier has exactly 16 elements — spot check a handful of
689	        // named ones from Table 1 of the paper are constructible and distinct.
690	        let n = Reg16_3::default();
691	        let a = Reg16_3 { big_t: true, big_f: true, small_t: true, small_f: true };
692	        let t = Reg16_3 { big_t: true, ..Default::default() };
693	        let tf = Reg16_3 { big_t: true, big_f: true, ..Default::default() };
694	        assert_eq!(n.name(), "N");
695	        assert_eq!(a.name(), "A");
696	        assert_eq!(t.name(), "T");
697	        assert_eq!(tf.name(), "TF");
698	        assert_ne!(n.name(), a.name());
699	    }
700	}
